paths={}
def op(path,method,tag,summary,scope='authenticated ownership or explicit grant',permission=None,schema=None,resp='PageInfo',public=False,write=False,status='200',extra=None):
 params=[{'name':'requestId','in':'header','required':False,'schema':short,'description':'Client correlation ID; server generates one if absent.'}]
 for part in path.split('{')[1:]:
  name=part.split('}')[0];params.append({'name':name,'in':'path','required':True,'schema':short if name=='providerKey' else uuid})
 if method=='get' and resp=='PageInfo':params += [{'name':'limit','in':'query','schema':{'type':'integer','minimum':1,'maximum':100,'default':20}},{'name':'cursor','in':'query','schema':short}]
 if write:
  params += [{'name':'Idempotency-Key','in':'header','required':True,'schema':{'type':'string','minLength':8,'maxLength':128}},{'name':'X-CSRF-Token','in':'header','required':True,'schema':short}]
 responses={status:{'description':'Authoritative result; no provider success is inferred from a redirect.','content':{'application/json':{'schema':ref(resp)}}},'default':{'description':'Stable error; no sensitive internals.','content':{'application/json':{'schema':ref('Error')}}}}
